<?php
require_once __DIR__.'/bakery_auth.php';$bakeryDb=bakeryDbOrFail();$bakeryAccount=requireBakerySession($bakeryDb);$error='';
$messages=['added'=>'Đã thêm khoản đầu tư.','updated'=>'Đã cập nhật khoản đầu tư.','deleted'=>'Đã xóa khoản đầu tư.'];$success=$messages[$_GET['success']??'']??'';
$form=['id'=>0,'investment_date'=>date('Y-m-d'),'category'=>'Xây dựng phần thô','description'=>'','contractor'=>'','amount'=>'','status'=>'paid','note'=>''];
$range=bakeryMonthRange($_SERVER['REQUEST_METHOD']==='POST'?$_POST:$_GET);
if($_SERVER['REQUEST_METHOD']==='POST'){
 csrf_require($_POST['csrf_token']??'');$action=(string)($_POST['action']??'');
 if($action==='delete'){$id=(int)($_POST['id']??0);$stmt=$bakeryDb->prepare('DELETE FROM bakery_investments WHERE id=?');$stmt->bind_param('i',$id);$stmt->execute();header('Location: bakery_investments.php?'.bakeryMonthRangeQuery($range,['success'=>'deleted']));exit;}
 if($action==='save'){$form=['id'=>(int)($_POST['id']??0),'investment_date'=>trim((string)($_POST['investment_date']??'')),'category'=>trim((string)($_POST['category']??'')),'description'=>trim((string)($_POST['description']??'')),'contractor'=>trim((string)($_POST['contractor']??'')),'amount'=>trim((string)($_POST['amount']??'')),'status'=>in_array($_POST['status']??'', ['planned','paid'],true)?$_POST['status']:'planned','note'=>trim((string)($_POST['note']??''))];$amount=bakeryMoneyInput($form['amount']);
  if(!bakeryValidDate($form['investment_date']))$error='Ngày đầu tư không hợp lệ.';elseif($form['description']===''||mb_strlen($form['description'],'UTF-8')>200)$error='Vui lòng nhập nội dung, tối đa 200 ký tự.';elseif($amount===null)$error='Số tiền phải lớn hơn 0.';elseif(mb_strlen($form['note'],'UTF-8')>1000)$error='Ghi chú tối đa 1.000 ký tự.';else{$id=(int)$form['id'];if($id){$stmt=$bakeryDb->prepare('UPDATE bakery_investments SET investment_date=?,category=?,description=?,contractor=?,amount=?,status=?,note=? WHERE id=?');$stmt->bind_param('sssssssi',$form['investment_date'],$form['category'],$form['description'],$form['contractor'],$amount,$form['status'],$form['note'],$id);$result='updated';}else{$user=(int)$bakeryAccount['id'];$stmt=$bakeryDb->prepare('INSERT INTO bakery_investments(investment_date,category,description,contractor,amount,status,note,created_by) VALUES(?,?,?,?,?,?,?,?)');$stmt->bind_param('sssssssi',$form['investment_date'],$form['category'],$form['description'],$form['contractor'],$amount,$form['status'],$form['note'],$user);$result='added';}$stmt->execute();$savedMonth=substr($form['investment_date'],0,7);if($savedMonth<$range['from_month']||$savedMonth>$range['to_month'])$range=bakeryMonthRange(['from_month'=>$savedMonth,'to_month'=>$savedMonth]);header('Location: bakery_investments.php?'.bakeryMonthRangeQuery($range,['success'=>$result]));exit;}}
}
if($_SERVER['REQUEST_METHOD']!=='POST'&&isset($_GET['edit'])){$id=(int)$_GET['edit'];$stmt=$bakeryDb->prepare('SELECT * FROM bakery_investments WHERE id=?');$stmt->bind_param('i',$id);$stmt->execute();if($row=$stmt->get_result()->fetch_assoc()){$form=$row;$form['amount']=number_format((float)$row['amount'],0,',','.');}}
$stmt=$bakeryDb->prepare('SELECT * FROM bakery_investments WHERE investment_date BETWEEN ? AND ? ORDER BY investment_date DESC,id DESC');$stmt->bind_param('ss',$range['from_date'],$range['to_date']);$stmt->execute();$rows=$stmt->get_result()->fetch_all(MYSQLI_ASSOC);$total=array_sum(array_map(fn($r)=>(float)$r['amount'],$rows));
?>
<!doctype html><html lang="vi"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Đầu tư phần thô</title></head><body><?php require __DIR__.'/bakery_nav.php';?><main class="bk-shell"><header class="bk-header"><div><h1>Đầu tư phần thô</h1><p>Theo dõi xây dựng, điện nước, thiết kế và các chi phí chuẩn bị mặt bằng.</p></div></header><?php if($error):?><div class="bk-alert bk-alert-error"><?=bakeryH($error)?></div><?php endif;?><?php if($success):?><div class="bk-alert bk-alert-success"><?=bakeryH($success)?></div><?php endif;?><div class="bk-grid bk-grid-2"><section class="bk-card"><h2 class="bk-card-title"><?=$form['id']?'Sửa khoản đầu tư':'Thêm khoản đầu tư'?></h2><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="save"><input type="hidden" name="id" value="<?=(int)$form['id']?>"><input type="hidden" name="from_month" value="<?=bakeryH($range['from_month'])?>"><input type="hidden" name="to_month" value="<?=bakeryH($range['to_month'])?>"><div class="bk-form-grid"><div><label class="bk-label">Ngày</label><input class="bk-input" type="date" name="investment_date" required value="<?=bakeryH($form['investment_date'])?>"></div><div><label class="bk-label">Hạng mục</label><select class="bk-select" name="category"><?php foreach(['Xây dựng phần thô','Điện nước','Thiết kế','Giấy phép','Sửa chữa','Khác'] as $v):?><option <?=$form['category']===$v?'selected':''?>><?=bakeryH($v)?></option><?php endforeach;?></select></div><div class="bk-span-2"><label class="bk-label">Nội dung</label><input class="bk-input" name="description" maxlength="200" required value="<?=bakeryH($form['description'])?>"></div><div><label class="bk-label">Nhà thầu / đơn vị</label><input class="bk-input" name="contractor" maxlength="150" value="<?=bakeryH($form['contractor'])?>"></div><div><label class="bk-label">Số tiền</label><input class="bk-input" data-bk-money inputmode="numeric" name="amount" maxlength="13" required value="<?=bakeryH($form['amount'])?>"></div><div class="bk-span-2"><label class="bk-label">Trạng thái</label><select class="bk-select" name="status"><option value="planned" <?=$form['status']==='planned'?'selected':''?>>Dự kiến</option><option value="paid" <?=$form['status']==='paid'?'selected':''?>>Đã thanh toán</option></select></div><div class="bk-span-2"><label class="bk-label">Ghi chú</label><textarea class="bk-textarea" name="note" maxlength="1000"><?=bakeryH($form['note'])?></textarea></div></div><button class="bk-btn bk-btn-primary bk-btn-block"><?=$form['id']?'Lưu thay đổi':'Thêm khoản đầu tư'?></button></form></section><section><form class="bk-filter"><div><label class="bk-label">Từ tháng</label><input class="bk-input" type="month" name="from_month" value="<?=bakeryH($range['from_month'])?>"></div><div><label class="bk-label">Đến tháng</label><input class="bk-input" type="month" name="to_month" value="<?=bakeryH($range['to_month'])?>"></div><button class="bk-btn bk-btn-secondary">Xem</button></form><div class="bk-total"><span>Tổng trong khoảng đã chọn</span><span><?=bakeryMoney($total)?></span></div><div class="bk-table-wrap"><table class="bk-table"><thead><tr><th>Ngày</th><th>Hạng mục</th><th>Nội dung</th><th>Nhà thầu</th><th>Trạng thái</th><th class="money">Số tiền</th><th></th></tr></thead><tbody><?php if(!$rows):?><tr><td colspan="7"><div class="bk-empty">Chưa có khoản đầu tư.</div></td></tr><?php endif;?><?php foreach($rows as $r):?><tr><td><?=date('d/m/Y',strtotime($r['investment_date']))?></td><td><?=bakeryH($r['category'])?></td><td><strong><?=bakeryH($r['description'])?></strong><div class="bk-muted"><?=bakeryH($r['note'])?></div></td><td><?=bakeryH($r['contractor']?:'—')?></td><td><span class="bk-badge <?=$r['status']==='paid'?'green':'orange'?>"><?=$r['status']==='paid'?'Đã thanh toán':'Dự kiến'?></span></td><td class="money"><?=bakeryMoney($r['amount'])?></td><td><div class="bk-actions"><a class="bk-btn bk-btn-secondary bk-btn-small" href="?<?=bakeryH(bakeryMonthRangeQuery($range,['edit'=>(int)$r['id']]))?>">Sửa</a><form method="post" onsubmit="return confirm('Xóa khoản đầu tư này?')"><?=csrf_field()?><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=(int)$r['id']?>"><input type="hidden" name="from_month" value="<?=bakeryH($range['from_month'])?>"><input type="hidden" name="to_month" value="<?=bakeryH($range['to_month'])?>"><button class="bk-btn bk-btn-danger bk-btn-small">Xóa</button></form></div></td></tr><?php endforeach;?></tbody></table></div></section></div></main><script>document.querySelectorAll('[data-bk-money]').forEach(function(e){function f(){let d=e.value.replace(/\D/g,'').replace(/^0+(?=\d)/,'');e.value=d.replace(/\B(?=(\d{3})+(?!\d))/g,'.')}e.addEventListener('input',f);f()})</script></body></html>
